#!/usr/bin/env python3
# SPDX-License-Identifier: BSD-2-Clause
"""Resolve scheduled build roots with the pinned native Homebrew bridge."""
import json
import os
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from intelbrew.ci import allowed_redistribution, sync_registry
from intelbrew.core import (
    Error,
    Planner,
    blocked_toolchain_source,
    canonical_name,
    load_config,
    native,
    registry,
    source_build_blocklist,
)

# GitHub Actions accepts at most 256 jobs generated by one matrix.
MATRIX_MAX_ROOTS = 256
INSPECT_BATCH_SIZE = 100


class CachedInspector:
    def __init__(self):
        self.cache = {}
        self.errors = {}

    def prime(self, names):
        names = [name for name in dict.fromkeys(names)
                 if name not in self.cache and name not in self.errors]
        for offset in range(0, len(names), INSPECT_BATCH_SIZE):
            self._prime_batch(names[offset:offset + INSPECT_BATCH_SIZE])

    def _prime_batch(self, batch):
        try:
            result = native({"mode": "inspect", "names": batch}, ci=True)
            if not isinstance(result, dict) or set(result) != set(batch):
                raise Error('Incomplete metadata/alias')
            self.cache.update(result)
        except (Error, KeyError, OSError, TypeError, ValueError) as exc:
            if len(batch) > 1:
                middle = len(batch) // 2
                self._prime_batch(batch[:middle])
                self._prime_batch(batch[middle:])
            elif batch:
                self.errors[batch[0]] = str(exc)

    def __call__(self, names):
        missing = [name for name in names if name not in self.cache]
        if missing:
            self.prime(missing)
        failed = [name for name in names if name in self.errors]
        if failed:
            name = failed[0]
            raise Error(f'{name}: native inspection failed: {self.errors[name]}')
        return {name: self.cache[name] for name in names}


def matrix_roots(candidates, *, max_roots=None):
    candidates = list(candidates)
    if max_roots is not None and max_roots > 0:
        candidates = candidates[:max_roots]
    if len(candidates) > MATRIX_MAX_ROOTS:
        raise Error(
            f'{len(candidates)} build candidates exceed the GitHub matrix limit '
            f'of {MATRIX_MAX_ROOTS}'
        )
    return list(candidates)


def escape_markdown_table_cell(text):
    if not isinstance(text, str):
        text = str(text)
    text = text.replace("\r\n", " ").replace("\r", " ").replace("\n", " ")
    entities = {
        "&": "&amp;", "<": "&lt;", ">": "&gt;",
        "\\": "&#92;", "|": "&#124;", "`": "&#96;", "*": "&#42;",
        "_": "&#95;", "[": "&#91;", "]": "&#93;", "(": "&#40;",
        ")": "&#41;", "#": "&#35;", "+": "&#43;", "-": "&#45;",
        ".": "&#46;", "!": "&#33;", "~": "&#126;", ":": "&#58;",
    }
    text = "".join(entities.get(char, char) for char in text)
    return text.strip()


def generate_step_summary(config, coverage):
    core_commit = config.get("core_commit", "unknown")
    brew_commit = config.get("brew_commit", "unknown")
    counts = coverage.get("counts", {})

    lines = [
        "## Homebrew Bottle Coverage Report",
        "",
        f"- **Homebrew Core Pin**: `{core_commit}`",
        f"- **Homebrew Engine Pin**: `{brew_commit}`",
        "",
        "> **Note**: Coverage is measured against the pinned Homebrew Core snapshot "
        f"(`{core_commit}`) and may lag the client's latest core.",
        "",
        "### Coverage Metrics",
        "",
        "| Metric | Count |",
        "| :--- | :--- |",
        f"| Inspected Roots | {counts.get('inspected', 0)} |",
        f"| Covered Roots | {counts.get('covered', 0)} |",
        f"| Eligible Roots | {counts.get('eligible', 0)} |",
        f"| Selected Roots | {counts.get('selected', 0)} |",
        f"| Waiting Roots (Batch Cap) | {counts.get('waiting', 0)} |",
        f"| Deferred Roots (Dependency Waves) | {counts.get('deferred', 0)} |",
        f"| Blocked Roots | {counts.get('blocked', 0)} |",
        f"| Coverage Complete | {'Yes' if coverage.get('coverage_complete') else 'No'} |",
        "",
    ]

    def append_bullets(title, values):
        lines.extend([f"### {title}", ""])
        if values:
            lines.extend(f"- {value}" for value in values)
        else:
            lines.append("*(none)*")
        lines.append("")

    append_bullets(
        "Selected Roots",
        [escape_markdown_table_cell(name) for name in coverage.get("selected_roots", [])],
    )
    append_bullets(
        "Waiting Roots (Batch Cap)",
        [escape_markdown_table_cell(name) for name in coverage.get("waiting_roots", [])],
    )

    deferred = coverage.get("deferred_roots", {})
    deferred_rows = [
        f"{escape_markdown_table_cell(name)} (dependencies: "
        f"{', '.join(escape_markdown_table_cell(dep) for dep in deferred[name])})"
        for name in sorted(deferred)
    ]
    append_bullets("Deferred Roots (Dependency Waves)", deferred_rows)

    lines.append("### Blocked Roots")
    lines.append("")
    blocked = coverage.get("blocked_roots", {})
    if blocked:
        lines.append("| Formula | Cause |")
        lines.append("| :--- | :--- |")
        for name in sorted(blocked):
            safe_name = escape_markdown_table_cell(name)
            safe_cause = escape_markdown_table_cell(blocked[name])
            lines.append(f"| {safe_name} | {safe_cause} |")
    else:
        lines.append("*(no blocked roots)*")
    lines.append("")

    return "\n".join(lines)


def evaluate_roots_coverage(roots, inspector, records, config, *, max_roots=None):
    inspector.prime(roots)
    candidates = {}
    blocked = {}
    covered = []
    for root in roots:
        try:
            plan = Planner(
                inspector,
                records,
                build=True,
                max_nodes=config['max_graph_nodes'],
                blocked=source_build_blocklist(config),
                holds=config.get('source_build_holds', []),
            ).make([root])
            excluded = blocked_toolchain_source(plan, config.get('blocked_source_builds', []))
            if excluded:
                raise Error(f'Source build excluded by policy: {excluded}')
            builds = [name for name in plan['order'] if plan['nodes'][name]['provider'] == 'build']
            if not builds:
                covered.append(root)
                continue
            if len(builds) > config['max_source_builds']:
                raise Error(f'{root}: source build budget exceeded')
            for name in builds:
                allowed_redistribution(plan['nodes'][name], config)
            candidates[root] = builds
        except (Error, KeyError, OSError, TypeError, ValueError) as exc:
            blocked[root] = str(exc)
    candidate_roots = set(candidates)
    needed = []
    deferred = {}
    for root, builds in candidates.items():
        # Build shared source dependencies as their own roots first.  A root
        # such as qtwebengine can otherwise compile the same Qt modules that
        # are already queued as independent roots, consuming its entire
        # six-hour GitHub-hosted runner budget before the root itself starts.
        dependencies = sorted(set(builds).intersection(candidate_roots) - {root})
        if dependencies:
            deferred[root] = dependencies
            continue
        needed.append((len(builds), root))
    needed.sort(key=lambda item: (item[0], item[1]))
    eligible = [root for _, root in needed]

    if max_roots is None or max_roots <= 0:
        # Compatibility callers inspect the complete catalog; only callers
        # allocating an Actions matrix need the 256-job limit.
        selected = list(eligible)
    else:
        selected = matrix_roots(eligible, max_roots=max_roots)
    waiting = eligible[len(selected):]

    coverage_complete = (len(covered) == len(roots))

    return {
        'inspected_roots': list(roots),
        'covered_roots': covered,
        'eligible_roots': eligible,
        'selected_roots': selected,
        'waiting_roots': waiting,
        'deferred_roots': deferred,
        'blocked_roots': blocked,
        'counts': {
            'inspected': len(roots),
            'covered': len(covered),
            'eligible': len(eligible),
            'selected': len(selected),
            'waiting': len(waiting),
            'deferred': len(deferred),
            'blocked': len(blocked),
        },
        'coverage_complete': coverage_complete,
    }


def roots_needing_build(roots, inspector, records, config):
    coverage = evaluate_roots_coverage(roots, inspector, records, config)
    return coverage['eligible_roots'], coverage['blocked_roots']


def main():
    try:
        payload = json.loads(os.environ['PLANNED_ROOTS'])
        roots = payload.get('root') if isinstance(payload, dict) else None
        if (not isinstance(roots, list) or not roots or len(roots) > 2000
                or any(not isinstance(root, str) for root in roots)):
            raise Error('Invalid planned roots')
        roots = [canonical_name(root) for root in roots]
        if len(roots) != len(set(roots)):
            raise Error('Planned roots contain duplicates')
        config = load_config()
        sync_registry()
        batch_size = config.get('scheduled_batch_size', 12)
        coverage = evaluate_roots_coverage(
            roots, CachedInspector(), registry(), config, max_roots=batch_size
        )
        selected = coverage['selected_roots']
        blocked = coverage['blocked_roots']
        deferred = coverage['deferred_roots']
        waiting = coverage['waiting_roots']
        eligible = coverage['eligible_roots']
        covered = coverage['covered_roots']
        coverage_complete = coverage['coverage_complete']

        if 'GITHUB_OUTPUT' in os.environ:
            with open(os.environ['GITHUB_OUTPUT'], 'a', encoding='utf-8') as handle:
                handle.write('matrix=' + json.dumps({'root': selected}, separators=(',', ':')) + '\n')
                handle.write('has_work=' + str(bool(selected)).lower() + '\n')
                handle.write('coverage_complete=' + str(bool(coverage_complete)).lower() + '\n')

        summary_path = os.environ.get('GITHUB_STEP_SUMMARY')
        if summary_path:
            with open(summary_path, 'a', encoding='utf-8') as handle:
                handle.write(generate_step_summary(config, coverage) + '\n')

        if not coverage_complete:
            parts = []
            if blocked:
                parts.append(f"{len(blocked)} blocked")
            if deferred:
                parts.append(f"{len(deferred)} deferred")
            if waiting:
                parts.append(f"{len(waiting)} waiting")
            if selected:
                parts.append(f"{len(selected)} selected for build")
            details = ", ".join(parts) if parts else "incomplete"
            print(
                f"::warning::Incomplete bottle coverage ({details}) "
                f"measured against pinned core {config['core_commit']}",
                file=sys.stderr,
            )

        print(json.dumps({
            'inspected_roots': len(roots),
            'build_candidates': len(eligible),
            'selected_roots': selected,
            'blocked_roots': blocked,
            'covered_roots': covered,
            'eligible_roots': eligible,
            'waiting_roots': waiting,
            'deferred_roots': deferred,
            'coverage_complete': coverage_complete,
            'counts': coverage['counts'],
        }, indent=2))
        return 0
    except (Error, KeyError, OSError, TypeError, ValueError) as exc:
        print(exc, file=sys.stderr)
        return 1


if __name__ == '__main__':
    raise SystemExit(main())
